use std::{hint::black_box, time::Instant};
fn scalar(s: &[u16]) -> bool { s.iter().all(|&m| m == s[0]) }
fn lanes32(s: &[u16]) -> bool { let a = [s[0]; 32]; s.chunks_exact(32).all(|c| c == a) }
fn lanes128(s: &[u16]) -> bool { let a = [s[0]; 128]; s.chunks_exact(128).all(|c| c == a) }
fn reduction(s: &[u16]) -> bool { s.iter().fold(0, |d, &m| d | (m ^ s[0])) == 0 }
fn main() {
    let raw = std::fs::read(std::env::args().nth(1).unwrap()).unwrap();
    let blocks: Vec<_> = raw.chunks_exact(2).map(|v| u16::from_le_bytes([v[0], v[1]])).collect();
    let modes: [(&str, fn(&[u16])->bool);4] = [("scalar",scalar),("lanes32",lanes32),("lanes128",lanes128),("reduction",reduction)];
    let expected: Vec<_> = blocks.chunks_exact(4096).map(scalar).collect();
    for round in 0..8 {
        for i in 0..4 {
            let (name, test) = modes[if round % 2 == 0 { i } else {3-i}];
            let start = Instant::now();
            let result: Vec<_> = black_box(&blocks).chunks_exact(4096).map(test).collect();
            let ms = start.elapsed().as_secs_f64()*1000.;
            assert_eq!(result,expected);
            if round > 0 { println!("{name} {ms:.4}"); }
        }
    }
    println!("uniform {} total {}", expected.iter().filter(|&&v|v).count(), expected.len());
}
